def f2(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    rings=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==2:
                ok=True
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        if (dr,dc)!=(0,0) and not(0<=r+dr<H and 0<=c+dc<W) or (g[r+dr][c+dc] if 0<=r+dr<H and 0<=c+dc<W else -1)!= (3 if (dr,dc)!=(0,0) else 2):
                            ok=False
                if ok: rings.append((r,c,r-1,r+1,c-1,c+1))
    rings.sort()
    (r1_,c1_,rm1,rx1,lc1,rc1),(r2_,c2_,rm2,rx2,lc2,rc2)=rings
    o=[row[:] for row in g]
    # each ring translates along its own line direction until center hits the perpendicular structure; here: swap column spans
    # rule found: each ring moves to the other ring's column span (keeping rows), recolor 3->1, keep its 2
    def place(cr,cc):
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                v=o[cr+dr][cc+dc]
                if v==3: o[cr+dr][cc+dc]=1
                elif v==0: o[cr+dr][cc+dc]=1
                # 2 kept
    # center rows painted fully (skip nonzero)
    for cr in {(rm1+rx1)//2,(rm2+rx2)//2}:
        for c in range(W):
            if o[cr][c]==0: o[cr][c]=1
    # center columns painted fully (skip nonzero)
    for cc in {(lc1+rc1)//2,(lc2+rc2)//2}:
        for r in range(H):
            if o[r][cc]==0: o[r][cc]=1
    # translate rings to each other's column span
    place(rm1,(lc2+rc2)//2)
    place(rm2,(lc1+rc1)//2)
    return o

