    for r in range(H):
        for c in range(W):
            if g[r][c]==2:
                ok=True
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        nr,nc=r+dr,c+dc
                        v=g[nr][nc] if 0<=nr<H and 0<=nc<W else -1
