        for c in range(W):
            if o[cr][c]==0: o[cr][c]=1
    def paint_col(cc):
        for r in range(H):
            if o[r][cc]==0: o[r][cc]=1
    def place(cr,cc):
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                if (dr or dc):
                    v=o[cr+dr][cc+dc]
                    if v==3: o[cr+dr][cc+dc]=1
