    horiz=len(hbar)>=len(vbar)
    def band_lines(L,axis):
        res=set()
        for x in L:
            for y in (x-1,x,x+1):
                if 0<=y<(h if axis==0 else w): res.add(y)
        return res
    def interior(Ring, axis):
        if axis==0:
            r0,r1=min(p[0] for p in Ring),max(p[0] for p in Ring)
            return set(range(r0+1,r1))
        else:
            c0,c1=min(p[1] for p in Ring),max(p[1] for p in Ring)
            return set(range(c0+1,c1))
