            I=interior(Ring, axis)
            B=band_lines([min(p[axis] for p in Ring) for _ in [0]], axis)
            for cell in Ring: fill.add(cell)
            for x in I: fill.add((x,cell[1-axis]) if axis==0 else (cell[0],x))
            for x in B:
                for cp in [(x,_) if axis==0 else (_,x)]:
                    for cc in [cp[1] for cp in [(x,min(p[1-axis] for p in Ring))]]: pass
    # simpler: collect per-axis cells
    if horiz:
