            for c in range(c0+1,c1):
                for r in range(h): fill.add((r,c))
            for r in range(r0-1,r1+2):
                for c in range(c0,c1+1): fill.add((r,c))
    else:
        band_cols=band_lines(vbar,1)
        for Ring in rings:
            r0,r1=min(p[0] for p in Ring),max(p[0] for p in Ring)
            c0,c1=min(p[1] for p in Ring),max(p[1] for p in Ring)
            for c in band_cols:
                for r in range(h): fill.add((r,c))
            for r in range(r0+1,r1):
                for c in range(c0,c1+1): fill.add((r,c))
    for (r,c) in fill:
        if o[r][c]==0 or (o[r][c]==2 and (r,c) not in {(min(p[0] for p in Ring),min(p[1] for p in Ring)) for Ring in rings}):
